---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Terminal stream: Shell commands the agent runs, with their output as it streams in.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change terminal-stream.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './terminal-stream.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="terminal-stream" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="tmx panel" data-reveal="flat">
  <div class="tmx-h"><span class="tmx-ic"><svg class="i s"><use href="#i-term"/></svg></span><span class="tmx-cwd">~/acme/web</span><span class="tmx-st"><span class="g"><span class="spin"></span></span><span class="tmx-sv num">Starting</span></span><span class="sp"></span><button class="pill ghost sm tmx-stop" aria-label="Stop the running command"><svg class="i xs"><use href="#i-stop"/></svg>Stop</button><button class="ib tmx-cp" aria-label="Copy the output" data-tip="Copy"><svg class="i s"><use href="#i-copy"/></svg></button></div>
  <div class="tmx-body" role="log" aria-label="Terminal output" tabindex="0"></div>
  <div class="fold shut tmx-ff"><div><div class="tmx-f"><span class="g"></span><span class="tmx-fs num"></span></div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './terminal-stream.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Terminal stream ---------- */
/* the shell commands the agent runs, as a compact terminal: where it runs and how it is going in the header, then each
   command with its output streaming in under it, and an exit code or a check with how long it took. Output longer than
   five lines folds to its last four. The output is code (12px mono on a 1.8 line height); everything around it, the header,
   the times, the agent's notes and the summary, is in the interface's own type. It sits on two columns (owner, 18 Nov): the
   header's terminal mark, each command's $ (an edit's pencil, a note's spark) and the summary's mark are centred in one 16px
   column 16px in, and the directory, the commands, their output and the notes' words all start 8px after it. It keeps no room
   for output still to come (owner, 17 Nov): the terminal grows as lines arrive (grow()) up to 420px, then its output scrolls
   under the header and keeps to its newest line */
.tmx{display:flex;flex-direction:column;max-height:420px;overflow:hidden}
.tmx>.dm-grow{max-height:420px;min-height:0}
.tmx-h{display:flex;align-items:center;gap:var(--dm-s-2);height:44px;flex:none;padding:0 var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.tmx-ic{width:16px;display:grid;place-items:center;color:var(--dm-fg2);flex:none}
/* (the directory and the state take a line as tall as their letters, so their words sit on the header's centre line) */
.tmx-cwd{min-width:0;flex:0 1 auto;font-size:12.5px;line-height:15px;color:var(--dm-fg2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmx-st{display:inline-flex;align-items:center;gap:6px;min-width:0;font-size:12px;line-height:15px;white-space:nowrap}
.tmx-st .g{display:grid;place-items:center;flex:none}
.tmx-st .spin{width:10px;height:10px}
.tmx-h .sp{flex:1}
/* a narrow card (a phone) keeps every part of the head whole, so the state never runs into Stop (fix, 23 Nov): the state, Stop
   and Copy never shrink; under 300px Stop shows its icon only (its label stays for screen readers), and under 250px the
   directory, which by then would show only an ellipsis, gives way */
.tmx-h{container:tmxh/inline-size}
.tmx-st,.tmx-h :is(.pill,.ib){flex:none}
@container tmxh (max-width:300px){.tmx .tmx-h .pill.tmx-stop{width:28px;padding:0;gap:0;justify-content:center;font-size:0}}
@container tmxh (max-width:250px){.tmx-cwd{display:none}}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.tmx :is(.ib,.pill):active,:root[data-style="clean"] .tmx .ib:active,:root [data-style="clean"] .tmx .ib:active,:root [data-style="clean"].tmx .ib:active{transform:none}
/* Copy's tick is the vivid mark green, in place of its icon and at its size (owner, 18 Nov) */
.tmx .ib.copied{color:var(--dm-ok-mark)!important}
@media (hover:hover) and (pointer:fine){.tmx .ib.copied:hover{color:var(--dm-ok-mark)!important}}
.tmx-body{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:var(--dm-s-2) 0;font-size:12px;line-height:1.8;scrollbar-width:thin;scrollbar-color:var(--dm-rail) transparent}
.tmx-body::-webkit-scrollbar{width:8px}
.tmx-body::-webkit-scrollbar-track{background:transparent}
.tmx-body::-webkit-scrollbar-thumb{background:var(--dm-rail);border:2px solid transparent;background-clip:padding-box;border-radius:var(--dm-r-pill)}
:root:not([data-style="soft"],[data-style="clean"]) .tmx-body:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::-webkit-scrollbar-thumb{border-radius:0}
/* the commands, their output and an edit's lines are code: mono, the only place it is used */
.tmx-body code{font:inherit;font-family:var(--dm-mono);font-size:12px}
.tmx-blk+.tmx-blk{margin-top:var(--dm-s-1)}
.tmx-cmd{display:flex;align-items:center;gap:var(--dm-s-2);padding:0 var(--dm-s-4)}
.tmx-p{width:16px;flex:none;display:grid;place-items:center;color:var(--dm-fg2)}
code.tmx-p{font-weight:500;color:var(--dm-accent-fg,var(--dm-fg))}
.tmx-c{flex:1;min-width:0;font-weight:500;color:var(--dm-fg);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tmx-m{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted);white-space:nowrap;flex:none}
.tmx-m .g{display:grid;place-items:center}
.tmx-m .spin{width:10px;height:10px}
.tmx-m .ok{display:grid;color:var(--dm-ok-mark)}
.tmx-m .add{color:var(--dm-add)}.tmx-m .del{color:var(--dm-del)}
/* the output wraps inside the panel, so a long line never pushes the page sideways */
.tmx-o{display:block;padding:0 var(--dm-s-4) 0 40px;color:var(--dm-fg2);white-space:pre-wrap;overflow-wrap:anywhere}
.tmx-l{display:block}
.tmx-l.ok{color:var(--dm-ok)}.tmx-l.bad{color:var(--dm-bad)}.tmx-l.mu{color:var(--dm-muted)}
.tmx-more{display:flex;align-items:center;gap:6px;width:calc(100% - 40px);margin:0 8px 0 32px;padding:0 8px;border-radius:var(--dm-r-sm);font-size:12px;line-height:inherit;text-align:left;color:var(--dm-muted);transition:color var(--dm-t-fast),background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.tmx-more:hover{color:var(--dm-fg);background:var(--dm-row)}}
.tmx-more .sp{flex:1}
.tmx-more svg{transition:transform var(--dm-t) var(--dm-ease)}
.tmx-more[aria-expanded="true"] svg{transform:rotate(180deg)}
/* folded lines are hidden once they have folded away, so nothing measures the clipped part as if it were drawn */
.tmx-blk .fold.shut>*{visibility:hidden;transition:visibility 0s var(--dm-t)}
/* what the agent says between commands: its spark in the marks' column and its words on the commands' column, shimmering
   while it is still working it out */
.tmx-note{display:flex;gap:var(--dm-s-2);margin:var(--dm-s-2) var(--dm-s-4);font-size:12.5px;line-height:1.5;color:var(--dm-fg2)}
.tmx-note>svg{flex:none;margin:3px 2px 0;color:var(--dm-accent-fg,var(--dm-accent))}
.tmx-note .shim{font-size:inherit}
/* once the run is over, the line at the foot: its mark in the marks' column and how many commands ran (a finished line has
   no clock, owner, 18 Nov) */
.tmx-f{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px}
.tmx-f .g{width:16px;display:grid;place-items:center;flex:none;color:var(--dm-ok-mark)}
.tmx-f.stop .g{color:var(--dm-muted)}.tmx-f.bad .g{color:var(--dm-bad-mark)}
/* the run's state in the header: a neutral tag while it runs, its words shimmering as every loader's do (owner, 19 Nov), then
   the green tint once it passes or the red one if it failed */
.tmx-st{height:22px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-chip);color:var(--dm-fg2);transition:background .3s,color .3s}
.tmx-sv.shim{font-size:inherit}
.tmx-st.ok,.tmx-st.ok .g{background:var(--dm-ok-bg);color:var(--dm-ok)}
.tmx-st.bad,.tmx-st.bad .g{background:var(--dm-bad-bg);color:var(--dm-bad)}
/* while it runs, a light sweeps along the header's lower edge */
.tmx-h{position:relative}
.tmx-h::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--dm-accent-mark,var(--dm-accent)),transparent) 0 0/40% 100% no-repeat;opacity:0;transition:opacity .4s;pointer-events:none}
.tmx.live .tmx-h::after{opacity:1;animation:tmxsweep 1.8s var(--dm-ease-io) infinite}
@keyframes tmxsweep{from{background-position:-60% 0}to{background-position:160% 0}}
/* each command and edit has a line down its left: neutral grey, the accent while it runs and red if it failed (colour only
   where it means something: what is running, and what failed) */
.tmx-blk{position:relative}
.tmx-blk::before{content:"";position:absolute;left:7px;top:4px;bottom:4px;width:2px;border-radius:1px;background:var(--dm-rail);transition:background .3s}
.tmx-blk[data-s="run"]::before{background:var(--dm-accent-mark,var(--dm-accent));animation:tmxpulse 1.4s var(--dm-ease-io) infinite}
.tmx-blk[data-s="bad"]::before{background:var(--dm-bad-mark)}
@keyframes tmxpulse{50%{opacity:.35}}
/* an edit shows the lines it changed, removed in red and added in green, each on its own tint; the words start on the
   output's column, their tint reaching 8px out round them */
.tmx-df{display:block;margin:2px var(--dm-s-4) var(--dm-s-1) 32px;border-radius:var(--dm-r-sm);overflow:hidden}
.tmx-df span{display:block;padding:0 var(--dm-s-2);white-space:pre-wrap;overflow-wrap:anywhere;color:var(--dm-fg2)}
.tmx-df .a{background:color-mix(in srgb,var(--dm-add) 10%,transparent)}.tmx-df .a::first-letter{color:var(--dm-add)}
.tmx-df .d{background:color-mix(in srgb,var(--dm-del) 10%,transparent)}.tmx-df .d::first-letter{color:var(--dm-del)}
/* a block cursor blinks after the newest line while the run goes on */
.tmx.live .tmx-body::after{content:"";display:block;width:7px;height:14px;margin:var(--dm-s-1) 0 0 40px;background:var(--dm-fg2);animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"],[data-style="clean"]) .tmx-h:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::after{background:repeating-linear-gradient(90deg,var(--dm-accent-mark) 0 6px,transparent 6px 12px);animation:tmxmarch .6s steps(4) infinite}
@keyframes tmxmarch{to{background-position:12px 0}}
:root:not([data-style="soft"],[data-style="clean"]) .tmx-blk:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{width:1px}
:root:not([data-style="soft"],[data-style="clean"]) .tmx-blk[data-s="run"]:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *))::before{animation:bpblink 1.1s steps(1,end) infinite}
/* Clean (owner, 18 Nov): an off-white head strip with the directory and the run's state, Stop and Copy 16px from the card's
   edges and the strip's hairline as 28px pills (owner, 23 Nov); the output on white, 16px in, with no coloured lines (the mark at each command's end says how it went)
   and the $ in grey; and once the run is over, the summary as the off-white foot strip */
:root[data-style="clean"] .tmx-h,:root [data-style="clean"] .tmx-h,:root [data-style="clean"].tmx-h{height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:0 16px;background:var(--dm-strip);border-bottom-color:var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .tmx-h::after,:root [data-style="clean"] .tmx-h::after,:root [data-style="clean"].tmx-h::after,:root[data-style="clean"] .tmx-blk::before,:root [data-style="clean"] .tmx-blk::before,:root [data-style="clean"].tmx-blk::before{display:none}
:root[data-style="clean"] .tmx .ib,:root [data-style="clean"] .tmx .ib,:root [data-style="clean"].tmx .ib{width:28px;height:28px}
:root[data-style="clean"] .tmx-body,:root [data-style="clean"] .tmx-body,:root [data-style="clean"].tmx-body{padding:12px 0}
:root[data-style="clean"] :where([data-c],.tip,.kbx-k.ghost) code.tmx-p,:root [data-style="clean"] :where([data-c],.tip,.kbx-k.ghost) code.tmx-p,:root [data-style="clean"]:where([data-c],.tip,.kbx-k.ghost) code.tmx-p{color:var(--dm-muted)}
:root[data-style="clean"] .tmx-note>svg,:root [data-style="clean"] .tmx-note>svg,:root [data-style="clean"].tmx-note>svg{color:var(--dm-fg2)}
:root[data-style="clean"] .tmx-f,:root [data-style="clean"] .tmx-f,:root [data-style="clean"].tmx-f{padding:var(--dm-strip-y) 16px;line-height:28px;font-size:12.5px;background:var(--dm-strip);border-top-color:var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .tmx-f:not(.stop,.bad) .g,:root [data-style="clean"] .tmx-f:not(.stop,.bad) .g,:root [data-style="clean"].tmx-f:not(.stop,.bad) .g{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .tmx-st,:root [data-style="clean"] .tmx-st,:root [data-style="clean"].tmx-st{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, copied, enter, grow, html } from '../core/core.js';
DM.def('terminal-stream', (r, c) => {
  const IC = { term:I('term'), stop:I('stop','xs'), copy:I('copy') };
  r.innerHTML = r.innerHTML.replace(/\{(\w+)\}/g, (m, k) => IC[k] || m);
  const root = $('.tmx', r), body = $('.tmx-body', r), st = $('.tmx-st', r), sv = $('.tmx-sv', r), stop = $('.tmx-stop', r), cp = $('.tmx-cp', r), ff = $('.tmx-ff', r), foot = $('.tmx-f', r);
  // no room is kept for output still to come (owner, 17 Nov): the terminal grows as lines arrive, up to its 420px, once its
  // entrance has played; then the output scrolls. Installed inside something else, it sizes to its content as it is
  if (r === c.st) Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  // what the agent does: each command with the lines it prints and how long it takes, then the one line where it says what
  // went wrong and the edit that fixes it. [text, tone] marks a line ok (green), bad (red) or mu (grey)
  const F = (n, kb) => 'dist/' + n.padEnd(22) + kb.padStart(6) + ' kB';
  const BUILD = [['> acme-web@2.4.0 build', 'mu'], ['> vite build', 'mu'], 'vite v6.2.1 building for production...', 'transforming...', ['✓ 1284 modules transformed.', 'ok'], 'rendering chunks...', 'computing gzip size...',
    ...[['index.html', '0.46'], ['assets/Home-1c9e.js', '3.12'], ['assets/Pricing-3f9a.js', '12.40'], ['assets/Cart-7b21.js', '9.86'], ['assets/Account-a04d.js', '7.31'], ['assets/Billing-52ce.js', '6.94'],
      ['assets/Bills-e8f3.js', '5.27'], ['assets/Team-0d6a.js', '4.88'], ['assets/Prefs-9a1b.js', '6.02'], ['assets/Docs-44f0.js', '8.15'], ['assets/Search-b7c2.js', '2.96'], ['assets/Modal-61de.js', '1.84'],
      ['assets/Chart-ef09.js', '21.73'], ['assets/Table-3a7e.js', '11.09'], ['assets/Form-c1d4.js', '4.41'], ['assets/Toast-8e2f.js', '1.12'], ['assets/dates-29bb.js', '18.30'], ['assets/vendor-8c1e.js', '98.12'],
      ['assets/index-4f2a.js', '42.31'], ['assets/index-9b7d.css', '18.92']].map(([n, kb]) => F(n, kb)), ['✓ built in 6.1s', 'ok']];
  const S = [
    { cmd:'npm install', ms:1900, out:['added 412 packages in 1.9s', 'found 0 vulnerabilities'] },
    { cmd:'npm run build', ms:6100, out:BUILD },
    { cmd:'npm test', ms:3400, exit:1, out:[['RUN  v3.0.5 ~/acme/web', 'mu'], ['✓ src/lib/cart.test.ts (14 tests)', 'ok'], ['× src/lib/price.test.ts (1 failed)', 'bad'], ['  × formats a yearly price', 'bad'],
      ['    Expected: "$240/yr"', 'ok'], ['    Received: "$240.00/yr"', 'bad'], ['Tests  1 failed | 23 passed (24)', 'bad']] },
    { note:'The test expects whole dollars, but formatPrice always adds cents. Dropping them for round amounts.', ms:1500 },
    { edit:'src/lib/price.ts', add:2, del:1, ms:1500, diff:["- return `$${n.toFixed(2)}/${per}`", '+ const v = Number.isInteger(n) ? String(n) : n.toFixed(2)', '+ return `$${v}/${per}`'] },
    { cmd:'npm test', ms:2900, out:[['✓ src/lib/cart.test.ts (14 tests)', 'ok'], ['✓ src/lib/price.test.ts (10 tests)', 'ok'], ['Tests  24 passed (24)', 'ok']] }
  ];
  // output longer than five lines folds to its last four, behind a button that says how many are hidden
  const TAIL = 4, GAP = 200;
  let vt = 0, halt = false, over = false;
  const log = [], ran = [];
  const clock = ms => { const s = Math.floor(ms / 1000); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
  const sec = ms => (ms / 1000).toFixed(1) + ' s';
  // time passes in steps of a quarter second at most, so the clock in the header keeps up; false once Stop is pressed
  const pass = async (ms, each) => {
    for (let t = 0; t < ms;){ if (halt) return false; const d = Math.min(250, ms - t); await c.wait(d); t += d; vt += d; if (!over) sv.textContent = 'Running · ' + clock(vt); each && each(t); }
    return !halt;
  };
  // a command or an edit: its $ (or the edit's pencil) in the marks' column, what it is, and a spinner and its time on the right
  function row(mark, text){
    const el = html(`<div class="tmx-blk" data-s="run"><div class="tmx-cmd">${mark === '$' ? '<code class="tmx-p">$</code>' : `<span class="tmx-p">${mark}</span>`}<code class="tmx-c"></code><span class="tmx-m"><span class="g"><span class="spin"></span></span><span class="t num"></span></span></div></div>`);
    $('.tmx-c', el).textContent = text; body.appendChild(el); enter(el); return el;
  }
  function lines(el){
    const more = html(`<button class="tmx-more" aria-expanded="false" hidden>${I('chev-d','xs')}<span></span><i class="sp"></i></button>`), hid = html('<div class="fold shut"><code class="tmx-o"></code></div>'), tail = html('<code class="tmx-o"></code>');
    const inner = hid.firstElementChild; hid.inert = true; el.append(more, hid, tail);
    const label = () => { const n = inner.children.length, open = !hid.classList.contains('shut'); $('span', more).textContent = open ? 'Show fewer lines' : `Show ${n} more line${n > 1 ? 's' : ''}`; more.setAttribute('aria-expanded', open); };
    more.onclick = () => { hid.inert = hid.classList.toggle('shut'); label(); };
    return ([text, tone]) => {
      const l = document.createElement('span'); l.className = 'tmx-l' + (tone ? ' ' + tone : ''); l.textContent = text; tail.appendChild(l);
      if (inner.children.length + tail.children.length > TAIL + 1) while (tail.children.length > TAIL) inner.appendChild(tail.firstElementChild);
      if (inner.children.length){ more.hidden = false; label(); }
    };
  }
  const halted = el => { $('.tmx-m .g', el).innerHTML = '<span class="tag">Stopped</span>'; el.dataset.s = 'stop'; };
  function finish(how){
    over = true; stop.hidden = true; root.classList.remove('live'); sv.classList.remove('shim');
    st.classList.toggle('ok', how === 'passed'); st.classList.toggle('bad', how === 'failed'); $('.g', st).innerHTML = I(how === 'passed' ? 'check' : 'stop', 'xs'); sv.textContent = how === 'passed' ? 'Passed' : how === 'failed' ? 'Failed' : 'Stopped';
    // each command counts once, however many times it ran; how it went is the header's tag, so the summary doesn't say it
    // again, and a finished line has no clock (owner, 18 Nov)
    const n = new Set(ran).size;
    $('.tmx-fs', foot).textContent = `Ran ${n} command${n === 1 ? '' : 's'}`;
    foot.className = 'tmx-f' + (how === 'stopped' ? ' stop' : how === 'failed' ? ' bad' : ''); $('.g', foot).innerHTML = I(how === 'passed' ? 'ok' : how === 'failed' ? 'alert' : 'stop');
    ff.classList.remove('shut');
  }
  // new output keeps the log on its newest line, unless the person has scrolled up to read; then it stays where they are
  let pinned = true;
  const stick = () => { if (pinned) body.scrollTop = body.scrollHeight; };
  c.on(body, 'scroll', () => { pinned = body.scrollTop + body.clientHeight >= body.scrollHeight - 24; });
  const mo = new MutationObserver(stick); mo.observe(body, { childList:true, subtree:true }); c.offs.push(() => mo.disconnect());
  const ro = new ResizeObserver(stick); ro.observe(body); c.offs.push(() => ro.disconnect());
  stop.onclick = () => { halt = true; };
  cp.onclick = () => copied(cp, log.join('\n'));
  root.classList.add('live'); sv.classList.add('shim');
  c.run(async () => {
    let last = 0;
    for (const k of S){
      if (!await pass(GAP)) return finish('stopped');
      if (k.note){
        const n = html(`<div class="tmx-note">${I('spark','xs')}<span class="shim"></span></div>`), w = $('span', n); w.textContent = k.note; body.appendChild(n); enter(n); log.push('# ' + k.note);
        const ok = await pass(k.ms); w.classList.remove('shim');
        if (!ok) return finish('stopped');
        continue;
      }
      if (k.edit){
        const el = row(I('edit','xs'), 'Edit ' + k.edit); el.dataset.s = 'edit';
